function t3.update(p15, p16, ...)
	if p15.size_fn then
		p15:size_fn()
	end

	if ui.get_alpha() == 1 then
		local v49 = ui.get_mouse_position()
		local v50 = p15:is_in_area(v49)
		local list = t3.list
		local v52 = common.is_button_down(1)

		if not v50 and not p15.is_dragging or not v52 or list.target ~= "" and list.target ~= p15.global_name then
			if not v52 then
				local v53 = render.screen_size()

				p15.position = vector(math.min(p15.ui_callbacks.x:get(), v53.x - p15.size.x), math.min(p15.ui_callbacks.y:get(), v53.y - p15.size.y))
				list.target = ""
				p15.is_dragging = false
				p15.drag_position = vector()
			end
		else
			list.target = p15.global_name

			if p15.is_dragging then
				p15.position = v49 - p15.drag_position
				p15:limit_positions(p16)
				p15.ui_callbacks.x:set(math.floor(p15.position.x))
				p15.ui_callbacks.y:set(math.floor(p15.position.y))
			else
				local v54 = render.screen_size()

				p15.position = vector(math.min(p15.ui_callbacks.x:get(), v54.x - p15.size.x), math.min(p15.ui_callbacks.y:get(), v54.y - p15.size.y))
				p15.is_dragging = true
				p15.drag_position = v49 - p15.position
			end
		end
	end

	p15:snap_to_guides(10)

	local v55 = render.screen_size()
	local v56 = v55.x / 2
	local v57 = v55.y / 2
	local v58 = color(155, 155, 155, 155)

	if p15._align_center_x and ui.get_alpha() == 1 and p15.is_dragging then
		render.line(vector(v56, 0), vector(v56, v55.y), v58, 2)
	end

	if p15._align_center_y and ui.get_alpha() == 1 and p15.is_dragging then
		render.line(vector(0, v57), vector(v55.x, v57), v58, 2)
	end

	p15:ins_function(...)
end

